<?php require __DIR__.'/../includes/bootstrap.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if($pdo&&$id){$pdo->prepare('DELETE FROM advertisements WHERE id=?')->execute([$id]);log_admin_activity('advertisement_deleted','Advertisement ID: '.$id);}header('Location: advertisements.php');exit;}$rows=$pdo?$pdo->query('SELECT id,name,slot,status,width,height FROM advertisements ORDER BY updated_at DESC')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advertisements</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Advertisements</h1><p><a class="btn" href="advertisement-edit.php">New advertisement</a> <a href="dashboard.php">Dashboard</a></p><div class="card" style="overflow:auto"><table style="width:100%"><tr><th>Name</th><th>Slot</th><th>Size</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slot'])?></td><td><?=e($r['width'].' x '.$r['height'])?></td><td><?=e($r['status'])?></td><td><a href="advertisement-edit.php?id=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete this advertisement?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></table><?php if(!$rows):?><p class="muted">No advertisements found.</p><?php endif;?></div></main></body></html>
